      {
        id: "javascript-c16-u5-l5-paginacao-baseada-em-cursor-para-listas-extensas",
        title: "Paginação por cursor (Keyset) versus OFFSET tradicional",
        subtitle: "Escalabilidade de rolagem · Eliminando lentidão em páginas profundas e itens duplicados",
        theory: "Paginação com OFFSET 100000 faz o banco ler e descartar 100.000 linhas antes de devolver 20. Além disso, se uma nova tarefa for criada enquanto o usuário rola a tela, itens são duplicados. A paginação por cursor usa WHERE (criada_em, id) < ($1, $2) LIMIT 20: o salto é instantâneo e imune a inserções concorrentes.",
        questions: [
          q("Qual é o problema de desempenho da paginação tradicional com OFFSET em bases com muitos registros?", "O banco precisa ler e descartar fisicamente todas as linhas anteriores ao OFFSET antes de devolver o lote", ["O OFFSET apaga dados das páginas visitadas","O banco trava quando o OFFSET é maior que 10"], "OFFSET 50000 força o banco a processar 50.000 registros desnecessariamente a cada requisição."),
          q("O que é a anomalia do \"item fantasma\" (duplicação de registros) ao paginar com OFFSET tradicional?", "Se um novo item for inserido na página 1 enquanto o usuário avança para a página 2, o último item da pág 1 reaparece na pág 2", ["Os itens mudam de cor na tela","O banco deleta as tarefas concluídas"], "Como o índice absoluto se desloca com novas inserções, itens são exibidos repetidos ao estudante."),
          q("Como a \"Paginação por Cursor\" (Keyset Pagination) resolve a lentidão de grandes saltos?", "Buscando registros a partir do identificador ou timestamp do último item visto: WHERE criada_em < $1 LIMIT 20", ["Calculando a raiz quadrada do ID","Salvando todas as páginas no navegador"], "O cursor aproveita o índice B-Tree para saltar diretamente para a próxima linha sem ler nada anterior."),
          q("O que a API deve devolver ao cliente para viabilizar a busca do próximo lote via cursor?", "Uma propriedade next_cursor (ex: string base64 codificando o timestamp e ID do último item retornado)", ["O comando SQL completo para o frontend rodar","A senha do administrador"], "O frontend simplesmente repassa ?cursor=xyz na próxima requisição para continuar de onde parou."),
          t("Qual método de paginação busca registros diretamente a partir da âncora do último item visto?", ["cursor"], "A paginação por cursor (ou keyset) garante tempo de resposta constante."),
          g("Complete a cláusula WHERE da paginação por cursor buscando tarefas anteriores ao cursor:", ["criada_em"], "Buscar a partir do timestamp do cursor aproveita o índice de data.", "WHERE usuario_id = $1 AND ____ < $2 ORDER BY criada_em DESC LIMIT 20"),
          o("Ordene o fluxo de navegação com paginação por cursor:", ["Cliente faz requisição inicial GET /api/tarefas?limite=20 sem cursor","Servidor consulta as 20 primeiras tarefas e extrai o timestamp do último item","Servidor devolve a lista e o campo next_cursor contendo a âncora do último registro","Cliente solicita o próximo lote enviando GET /api/tarefas?cursor=xyz&limite=20"], "Requisição inicial, extração da âncora, resposta com next_cursor e busca subsequente."),
          p("Associe o estilo de paginação ao seu trade-off:", [["OFFSET / LIMIT","Fácil de implementar e permite saltar para página arbitrária, mas degrada sob volume"],["Cursor / Keyset","Tempo de resposta constante O(1) e sem duplicatas, ideal para scroll infinito"],["next_cursor","Token opaco que encapsula o ponto de parada do lote anterior"],["Anomalia de Deslocamento","Itens duplicados causados por inserções concorrentes durante paginação"]], "Adotar paginação por cursor viabiliza feeds de tarefas e históricos de alta performance.")
        ]
      }
